  "admin.forms.section_title": {
    lv: "Sistēma un noklusējumi jaunajiem lietotājiem",
    en: "System defaults for new users",
    fr: "Système et valeurs par défaut pour nouveaux utilisateurs",
    de: "Systemstandard für neue Nutzer",
    es: "Sistema y valores por defecto para nuevos usuarios",
    pt: "Sistema e predefinições para novos utilizadores",
    ru: "Системные настройки по умолчанию для новых пользователей",
  },
  "admin.forms.hint_main": {
    lv: "Nosaukumu lieto vietnē (<title>). Laika un datuma parametri kopējas jaunā konta laukos users.display_preferences pie reģistrācijas; katrs lietotājs pēc tam var mainīt savā sadaļā Iestatījumi. Izmaiņu saglabāšana uz serveri (~0.45 s pēc rakstīšanas) parādās kā peldoša ziņa – tāpat kā profila Iestatījumos. Dodoties prom no lapas, ja ir vietējas izmaiņas, vienreiz mēģina saglabāt klusi (bez toast).",
    en: "The name feeds <title>. Time/date defaults sync into users.display_preferences when someone registers; they can customize later under Settings. Autosaves to the server after ~0.45s idle; progress shows as toast popups (same UX as Profile settings). Leaving the page flushes silently once if needed.",
    fr: "Le nom alimente <title>. Les réglages date/heure rejoignent users.display_preferences à l’inscription et restent éditables dans Paramètres. Sauvegarde auto ~0,45 s ; progression en toast comme dans Réglages. Sortie : tentative de flush silencieux une fois si besoin.",
    de: "Name landet im <title>. Datum/Zeit-Defaults liegen nach Registrierung in users.display_preferences und sind unter Einstellungen änderbar. Nach ~0,45 s speichern, Fortschritt per Toast wie in Profil‑Einstellungen; beim Verlassen ggf. stilles Zwischenspeichern.",
    es: "El nombre aparece en <title>. Fecha y hora se copian en users.display_preferences al crear la cuenta; luego editable en Configuración. Guardado automático tras ~0,45 s con toasts igual que en Ajustes. Al salir, un último flush silencioso si hace falta.",
    pt: "O nome aparece em <title>. Data/hora vão para users.display_preferences ao registar-se; pode editar mais tarde nas Definições. Gravar automaticamente ao fim de ~0,45 s com toast como no perfil. Ao sair, tentativa silenciosa de flush se preciso.",
    ru: "Имя передает <title>. Значения времени и даты по умолчанию синхронизируются с файлом user.display_preferences, когда кто-то регистрируется; их можно будет настроить позже в настройках. Автосохранение на сервер после ~0,45 с простоя; прогресс отображается в виде всплывающих окон (тот же интерфейс, что и в настройках профиля). При выходе из страницы страница автоматически сбрасывается один раз, если это необходимо.",
  },
