  "landing.faq.a_saved": {
    lv: "Jā. Pēc reģistrācijas un pieslēgšanās tavi maksājumi un abonementi tiek saglabāti droši tavā kontā mākonī. Pie datiem piekļūsti tikai tu. Demonstrācijas lapās redzami tikai paraugi - tur nekas netiek saglabāts.",
    en: "Yes. After you sign up and log in, your payments and subscriptions are stored securely in your cloud account. Only you can access your data. Demo pages show samples only and nothing is saved there.",
    fr: "Oui. Après inscription et connexion, vos paiements et abonnements sont enregistrés en toute sécurité sur votre compte. Vous seul y accédez. Les pages démo affichent des exemples sans enregistrement.",
    de: "Ja. Nach Registrierung und Anmeldung werden Ihre Zahlungen und Abos sicher in Ihrem Cloud-Konto gespeichert. Nur Sie haben Zugriff. Demoseiten zeigen nur Beispiele ohne Speicherung.",
    es: "Sí. Tras registrarte e iniciar sesión, tus pagos y suscripciones se guardan de forma segura en tu cuenta en la nube. Solo tú accedes a tus datos. Las páginas demo muestran ejemplos y no guardan nada.",
    pt: "Sim. Após registo e início de sessão, os seus pagamentos e subscrições ficam guardados com segurança na sua conta na nuvem. Só você acede aos seus dados. As páginas de demonstração mostram exemplos sem guardar alterações.",
    ru: "Да. После регистрации и входа ваши платежи и подписки надёжно хранятся в облачном аккаунте. Доступ только у вас. На демо-страницах показываются примеры без сохранения.",
  },
